import fs from 'node:fs/promises';
import path from 'node:path';
const [siteDir='outputs/site',base='http://127.0.0.1:9471',output='outputs/browser-layout/all-pages.json']=process.argv.slice(2);
const pages=(await fs.readdir(siteDir)).filter(n=>n.endsWith('.html')).sort();
if(!pages.length)throw new Error('No generated HTML pages; no browser validation performed');
const source=await fs.readFile(new URL(import.meta.url),'utf8');
const version=await (await fetch('http://127.0.0.1:9233/json/version')).json();
const socket=new WebSocket(version.webSocketDebuggerUrl);
await new Promise((resolve,reject)=>{socket.onopen=resolve;socket.onerror=reject;});
let id=0,current=null;const waiting=new Map(),errors=[];
socket.onmessage=e=>{const r=JSON.parse(e.data);if(r.id){const p=waiting.get(r.id);waiting.delete(r.id);r.error?p.reject(new Error(JSON.stringify(r.error))):p.resolve(r.result);}else if(r.method==='Runtime.exceptionThrown'&&current){errors.push({...current,exception:r.params.exceptionDetails.exception?.description||r.params.exceptionDetails.text});}};
function call(method,params={},sessionId){const n=++id;return new Promise((resolve,reject)=>{waiting.set(n,{resolve,reject});socket.send(JSON.stringify({id:n,method,params,...(sessionId?{sessionId}:{})}));});}
const {targetId}=await call('Target.createTarget',{url:'about:blank'});
const records=[];let report;
try{
 const {sessionId}=await call('Target.attachToTarget',{targetId,flatten:true});
 const page=(method,params={})=>call(method,params,sessionId);
 await page('Page.enable');await page('Runtime.enable');await page('Network.enable');
 await page('Network.setCacheDisabled',{cacheDisabled:true});
 for(const width of [1440,390]){
  await page('Emulation.setDeviceMetricsOverride',{width,height:1000,deviceScaleFactor:1,mobile:width<600});
  for(const name of pages){
   current={page:name,width};
   const navigation=await page('Page.navigate',{url:base+'/'+encodeURIComponent(name)+'?layout='+Date.now()});
   if(navigation.errorText)throw new Error(name+': '+navigation.errorText);
   let ready=false;
   for(let i=0;i<50;i++){
    await new Promise(r=>setTimeout(r,100));
    const response=await page('Runtime.evaluate',{expression:`document.readyState==='complete' && decodeURIComponent(location.pathname).endsWith(${JSON.stringify('/'+name)})`,returnByValue:true});
    if(response.result.value){ready=true;break;}
   }
   if(!ready)throw new Error(name+': navigation did not complete within five seconds');
   await new Promise(r=>setTimeout(r,150));
   const response=await page('Runtime.evaluate',{expression:`(async()=>{await Promise.race([document.fonts.ready,new Promise((_,reject)=>setTimeout(()=>reject(new Error('Fonts timed out')),12000))]);await Promise.race([Promise.all([...document.images].map(i=>i.decode().catch(()=>null))),new Promise((_,reject)=>setTimeout(()=>reject(new Error('Images timed out')),12000))]);const main=document.querySelector('.md-typeset');if(!main)throw new Error('No main text');const ids=[...document.querySelectorAll('[id]')].map(e=>e.id);const rect=e=>({width:e.getBoundingClientRect().width,height:e.getBoundingClientRect().height});return {title:document.title,viewport:innerWidth,document_width:document.documentElement.scrollWidth,main:rect(main),body_font:getComputedStyle(main).fontSize,broken_images:[...document.images].filter(i=>!i.complete||!i.naturalWidth).map(i=>i.getAttribute('src')),duplicate_ids:[...new Set(ids.filter((id,i)=>ids.indexOf(id)!==i))],figures:[...document.querySelectorAll('.illustration')].map(e=>({figure:rect(e),image:rect(e.querySelector('img')),source:e.querySelector('img').getAttribute('src')})),output_count:document.querySelectorAll('.output').length,downloads:[...document.querySelectorAll('a')].filter(a=>a.getAttribute('href')?.endsWith('.ipynb')).map(a=>a.getAttribute('href')),colab:[...document.querySelectorAll('a')].filter(a=>a.href.startsWith('https://colab.research.google.com/')).map(a=>a.href)}})()`,awaitPromise:true,returnByValue:true});
   if(response.exceptionDetails)throw new Error(JSON.stringify(response.exceptionDetails));
   records.push({...current,...response.result.value});
   if(records.length%20===0)console.log(JSON.stringify({checked:records.length,total:pages.length*2,last:current}));
  }
 }
 const failures=records.filter(r=>r.document_width>r.viewport+1||r.broken_images.length||r.duplicate_ids.length);
 report={schema_version:1,checked_at:new Date().toISOString(),status:failures.length||errors.length?'failed':'passed',scope:'Actual Chromium navigation of each generated HTML page at 1440 and 390 CSS pixels, with fonts and images loaded. Document overflow, duplicate IDs, broken images, figure dimensions and notebook/Colab links are recorded. This does not replace visual inspection, source review or remote Colab execution.',browser:version.Browser,build_info:JSON.parse(await fs.readFile(path.join(siteDir,'build-info.json'),'utf8')),verification_program:source,page_count:pages.length,viewport_count:2,records,failures,runtime_errors:errors};
 await fs.mkdir(path.dirname(output),{recursive:true});
 await fs.writeFile(output,JSON.stringify(report,null,2)+'\n');
 console.log(JSON.stringify({status:report.status,page_count:pages.length,checked:records.length,failures:failures.length,runtime_errors:errors.length,output}));
 if(report.status!=='passed')process.exitCode=1;
}finally{await call('Target.closeTarget',{targetId});socket.close();}
